// Tile art for maps: draws wall pieces from TileArtStyles (generated by ships/tilegen.py) into a
// map's tileset, and writes the tileset back into the map's .lvl prefix.
//
// A wall piece is chosen by its eight neighbours (mask bits N=1 NE=2 E=4 SE=8 S=16 SW=32 W=64
// NW=128; a diagonal counts only when both sides next to it are open: 47 pieces). Pieces drawn
// for the same mask in the same style join seamlessly with their neighbours.
//
//   usage(grid)        how the map uses each wall slot: its commonest neighbour mask
//   groups(grid, use)  slots that touch each other in the map (one structure: one style)
//   blankPlan / restylePlan / sheetPlan   which slot gets which style and piece
//   paint(base, plan)  a new 304x160 tileset canvas
//   withTileset(prefix, canvas)  the map's new .lvl prefix (24-bit BMP, eLVL data kept)
//   mount(el, editor)  the "Tile art" panel in the map editor: one dropdown of whole tilesets the
//                      editor offers (the pilot's own, the standard tiles) and the generated styles
// Pure parts (no DOM) are exported for node tests through module.exports.
"use strict";

(() => {
  const TS = 16, COLS = 19, ROWS = 10;
  const N = 1, NE = 2, E = 4, SE = 8, S = 16, SW = 32, W = 64, NW = 128;
  const SIDES = { N, E, S, W };
  const isWall = (t) => t >= 1 && t <= 161;

  function canon(m) {
    let c = m & (N | E | S | W);
    for (const [d, a, b] of [[NE, N, E], [SE, S, E], [SW, S, W], [NW, N, W]]) if (m & d && m & a && m & b) c |= d;
    return c;
  }
  // A layout role's open set as a mask: roles say nothing about diagonals, so inner corners are filled.
  function openMask(open) {
    let m = NE | SE | SW | NW;
    for (const ch of open) m |= SIDES[ch] || 0;
    return canon(m);
  }

  const DIRS = [[N, 0, -1], [NE, 1, -1], [E, 1, 0], [SE, 1, 1], [S, 0, 1], [SW, -1, 1], [W, -1, 0], [NW, -1, -1]];

  // Map(slot -> { mask, count, masks: Map(mask -> n) }) for every wall slot the map places.
  function usage(grid, n = 1024) {
    const out = new Map();
    for (let y = 0; y < n; y++) for (let x = 0; x < n; x++) {
      const t = grid[y * n + x];
      if (!isWall(t)) continue;
      let m = 0;
      for (const [bit, dx, dy] of DIRS) {
        const xx = x + dx, yy = y + dy;
        if (xx >= 0 && yy >= 0 && xx < n && yy < n && isWall(grid[yy * n + xx])) m |= bit;
      }
      m = canon(m);
      let u = out.get(t);
      if (!u) out.set(t, u = { mask: 0, count: 0, masks: new Map() });
      u.count++;
      u.masks.set(m, (u.masks.get(m) || 0) + 1);
    }
    for (const u of out.values()) {
      let best = -1;
      for (const [m, k] of u.masks) if (k > best || (k === best && m < u.mask)) { best = k; u.mask = m; }
    }
    return out;
  }

  // Slots whose tiles sit next to each other in the map, as arrays, biggest (most tiles) first.
  function groups(grid, use, n = 1024) {
    const parent = new Map();
    const find = (a) => { while (parent.get(a) !== a) { parent.set(a, parent.get(parent.get(a))); a = parent.get(a); } return a; };
    for (const t of use.keys()) parent.set(t, t);
    for (let y = 0; y < n; y++) for (let x = 0; x < n; x++) {
      const t = grid[y * n + x];
      if (!isWall(t)) continue;
      for (const [u, v] of [[x + 1, y], [x, y + 1]]) {
        if (u >= n || v >= n) continue;
        const o = grid[v * n + u];
        if (isWall(o) && o !== t) { const a = find(t), b = find(o); if (a !== b) parent.set(a, b); }
      }
    }
    const sets = new Map();
    for (const t of use.keys()) { const r = find(t); if (!sets.has(r)) sets.set(r, []); sets.get(r).push(t); }
    const weight = (g) => g.reduce((s, t) => s + use.get(t).count, 0);
    return [...sets.values()].map((g) => g.sort((a, b) => a - b)).sort((a, b) => weight(b) - weight(a) || a[0] - b[0]);
  }

  // Styles to use, in order: a theme's packs (by the layout's pack order) or one style.
  function stylesFor(choice, data) {
    const th = data.themes[choice];
    if (th) return [...new Set(Object.values(th))];
    return [choice];
  }

  // plan: Map(slot -> { style, mask })
  // Blank slots: each gets the piece its walls call for; a structure keeps one style. Unused
  // blank slots get the layout's piece for that slot when it has one, else a single block.
  function blankPlan(blank, grid, choice, data, layout) {
    const use = usage(grid);
    const styles = stylesFor(choice, data);
    const plan = new Map();
    const mine = new Map([...use].filter(([t]) => blank.has(t)));
    groups(grid, mine).forEach((g, i) => { for (const t of g) plan.set(t, { style: styles[i % styles.length], mask: mine.get(t).mask }); });
    const fromLayout = sheetPlan(layout, choice, data);
    for (const t of blank.keys()) if (isWall(t) && !plan.has(t)) plan.set(t, fromLayout.get(t) || { style: styles[0], mask: 0 });
    return plan;
  }

  // Every wall slot: the layout's packs first, then the slots the map uses redrawn as the piece
  // its walls call for (so maps that don't follow the standard layout still join up). On a map that
  // follows the layout, the slots the layout claims keep their pack's style and piece: only the
  // other slots are redrawn from how the map uses them.
  function restylePlan(grid, choice, data, layout) {
    const plan = sheetPlan(layout, choice, data);
    const use = usage(grid);
    const claimed = followsLayout(use, layout) ? layoutSlots(layout) : new Map();
    const free = new Map([...use].filter(([t]) => !claimed.has(t)));
    const styles = stylesFor(choice, data);
    groups(grid, free).forEach((g, i) => { for (const t of g) plan.set(t, { style: styles[i % styles.length], mask: free.get(t).mask }); });
    return plan;
  }

  // Map(slot -> { pack, index, mask }) for every wall slot the layout's packs name: their roles,
  // and the optional interior (wall all round), calm edges (an edge, plain inside) and inner
  // corners (wall all round but the one open diagonal).
  const DIAG = { NE, SE, SW, NW };
  function layoutSlots(layout) {
    const out = new Map();
    const roles = (layout && layout.roles) || {};
    ((layout && layout.packs) || []).forEach((p, index) => {
      const put = (t, mask) => { if (isWall(t) && !out.has(t)) out.set(t, { pack: p.id, index, mask }); };
      for (const [role, t] of Object.entries(p.tiles || {})) if (roles[role]) put(t, openMask(roles[role].open));
      if (p.interior != null) put(p.interior, 255);
      for (const [open, t] of Object.entries(p.calm || {})) put(t, openMask(open));
      for (const [d, t] of Object.entries(p.inner || {})) if (DIAG[d]) put(t, 255 & ~DIAG[d]);
    });
    return out;
  }

  // Does the map place the layout's slots as the layout means them? Most placements of claimed
  // slots must have the claimed open sides (diagonals aside).
  function followsLayout(use, layout) {
    const claimed = layoutSlots(layout);
    let hit = 0, all = 0;
    for (const [t, u] of use) {
      const c = claimed.get(t); if (!c) continue;
      for (const [m, k] of u.masks) { all += k; if ((m & 85) === (c.mask & 85)) hit += k; }
    }
    return all > 0 && hit / all >= 0.6;
  }

  // The style a pack is drawn in for a tile-art choice (a theme's style for that pack, or the one style).
  function packStyle(choice, packId, data, layout) {
    const th = data.themes[choice];
    if (th) {
      if (th[packId]) return th[packId];
      const styles = stylesFor(choice, data);
      const i = ((layout && layout.packs) || []).findIndex((p) => p.id === packId);
      return styles[Math.max(0, i) % styles.length];
    }
    return choice;
  }

  // A whole sheet in the layout: each pack in the theme's style for it (or the one style chosen).
  function sheetPlan(layout, choice, data) {
    const plan = new Map();
    const styles = stylesFor(choice, data);
    for (const [t, c] of layoutSlots(layout)) plan.set(t, { style: packStyle(choice, c.pack, data, layout), mask: c.mask });
    for (let t = 1; t <= 161; t++) if (!plan.has(t)) plan.set(t, { style: styles[t % styles.length], mask: 0 });
    return plan;
  }

  // ---- BMP -----------------------------------------------------------------------------------
  // rgba: 304*160*4 bytes, top-down. Returns a .lvl prefix: a 24-bit BMP, with the old prefix's
  // eLVL data (regions, attributes) appended and pointed to as the eLVL spec says.
  function withTileset(prefix, rgba, w = COLS * TS, h = ROWS * TS) {
    let elvl = null;
    if (prefix && prefix.length >= 8) {
      const dv = new DataView(prefix.buffer, prefix.byteOffset, prefix.byteLength);
      if (prefix[0] === 0x42 && prefix[1] === 0x4d) {
        const at = dv.getUint32(6, true), size = dv.getUint32(2, true);
        if (at > 0 && at < size && size <= prefix.length) elvl = prefix.slice(at, size);
      } else if (String.fromCharCode(prefix[0], prefix[1], prefix[2], prefix[3]) === "elvl") {
        elvl = prefix.slice();
      }
    }
    const row = (w * 3 + 3) & ~3, pix = row * h, head = 54;
    const elvlAt = elvl ? (head + pix + 3) & ~3 : 0;
    const total = elvl ? elvlAt + elvl.length : head + pix;
    const out = new Uint8Array(total);
    const dv = new DataView(out.buffer);
    out[0] = 0x42; out[1] = 0x4d;
    dv.setUint32(2, total, true); dv.setUint32(6, elvlAt, true); dv.setUint32(10, head, true);
    dv.setUint32(14, 40, true); dv.setInt32(18, w, true); dv.setInt32(22, h, true);
    dv.setUint16(26, 1, true); dv.setUint16(28, 24, true); dv.setUint32(30, 0, true);
    dv.setUint32(34, pix, true); dv.setInt32(38, 2835, true); dv.setInt32(42, 2835, true);
    for (let y = 0; y < h; y++) {
      const o = head + (h - 1 - y) * row;
      for (let x = 0; x < w; x++) {
        const i = (y * w + x) * 4;
        out[o + x * 3] = rgba[i + 2]; out[o + x * 3 + 1] = rgba[i + 1]; out[o + x * 3 + 2] = rgba[i];
      }
    }
    if (elvl) out.set(elvl, elvlAt);
    return out;
  }

  const api = { TS, COLS, ROWS, canon, openMask, usage, groups, stylesFor, blankPlan, restylePlan, sheetPlan, layoutSlots, followsLayout, packStyle, withTileset, isWall };
  if (typeof module !== "undefined" && module.exports) { module.exports = api; return; }

  // ---- browser ---------------------------------------------------------------------------------
  const data = window.TileArtStyles;
  const atlases = new Map(), reserved = new Map();
  const loadImg = (src, into, id) => into.has(id) ? null : new Promise((res, rej) => {
    const im = new Image();
    im.onload = () => { into.set(id, im); res(); };
    im.onerror = () => rej(new Error("tile art " + id + " did not load"));
    im.src = src;
  });
  const ready = () => Promise.all(data.styles.flatMap((s) => [loadImg(s.atlas, atlases, s.id), loadImg(s.reserved, reserved, s.id)]));
  let layoutP = null;
  const layout = () => layoutP || (layoutP = fetch("/arena/tile-layout.json").then((r) => r.ok ? r.json() : null).catch(() => null));

  // A new tileset canvas: base (or black) with plan's pieces drawn over their slots.
  // Without a base, slots 162-190 (doors, safe zone...) come from the first style's reserved row.
  function paint(base, plan, firstStyle) {
    const c = document.createElement("canvas"); c.width = COLS * TS; c.height = ROWS * TS;
    const ctx = c.getContext("2d");
    ctx.fillStyle = "#000"; ctx.fillRect(0, 0, c.width, c.height);
    if (base) ctx.drawImage(base, 0, 0);
    else if (reserved.has(firstStyle)) {
      const im = reserved.get(firstStyle);
      for (let t = 162; t <= 190; t++) { const i = t - 1; ctx.drawImage(im, (t - 162) * TS, 0, TS, TS, (i % COLS) * TS, Math.floor(i / COLS) * TS, TS, TS); }
    }
    for (const [t, { style, mask }] of plan) {
      const im = atlases.get(style); if (!im) continue;
      const k = data.masks.indexOf(canon(mask)); if (k < 0) continue;
      const i = t - 1;
      ctx.clearRect((i % COLS) * TS, Math.floor(i / COLS) * TS, TS, TS);
      ctx.drawImage(im, k * TS, 0, TS, TS, (i % COLS) * TS, Math.floor(i / COLS) * TS, TS, TS);
    }
    return c;
  }
  const rgbaOf = (c) => c.getContext("2d").getImageData(0, 0, c.width, c.height).data;

  // The panel. editor: { get() -> { grid, prefix, tileset, blank: Map }, set(prefix, tileset, note),
  //   optional: use(value, label) -> Promise<bool> puts one of the offered whole tilesets in the map,
  //   ask(text, opts) -> Promise<bool> instead of Dlg.confirm }.
  // Returns { refresh, forget, setSources([{ group, label, value }]) }: the offered tilesets go
  // above the styles; the pilot's own one ("Your tilesets") is picked first when there is one.
  function mount(el, editor) {
    if (!el || !data) return;
    const h = (tag, props, ...kids) => { const e = Object.assign(document.createElement(tag), props || {}); e.append(...kids); return e; };
    const ask = editor.ask || ((t, o) => (window.Dlg ? Dlg.confirm(t, o) : Promise.resolve(confirm(t))));
    const pick = h("select", { id: "tileartstyle", title: "A whole tileset to use, or a style to draw new wall art in", "aria-label": "Tile art" });
    const og1 = h("optgroup", { label: "Mixed (a style per structure)" });
    for (const id of Object.keys(data.themes)) og1.append(h("option", { value: id, textContent: id[0].toUpperCase() + id.slice(1) }));
    const og2 = h("optgroup", { label: "One style" });
    for (const s of data.styles) og2.append(h("option", { value: s.id, textContent: s.name }));
    pick.append(og1, og2);
    const preview = h("canvas", { className: "px", width: 4 * TS, height: TS, title: "A few pieces in this style" });
    const bBlank = h("button", { type: "button", className: "ghost small", textContent: "Paint blank slots", title: "Draw art into the tileset slots this map fills with one flat colour, each as the piece its walls need" });
    const bAll = h("button", { type: "button", className: "ghost small", textContent: "Restyle all walls", title: "Redraw every wall slot this map uses (and the rest of the standard layout) in the chosen style" });
    const bUse = h("button", { type: "button", className: "ghost small", textContent: "Use in this map", hidden: true, title: "Put this tileset in the map you're editing (published with it)" });
    const bBack = h("button", { type: "button", className: "ghost small", textContent: "Put old tiles back", hidden: true });
    const note = h("p", { className: "hint" });
    el.replaceChildren(h("div", { className: "row" }, pick, preview), h("div", { className: "row" }, bUse, bBlank, bAll, bBack), note);
    const STYLE_NOTE = "Generated wall art that joins up. Pieces are chosen from how the map uses each slot.";
    let sources = new Map(), touched = false;
    const isSource = () => sources.has(pick.value);
    const showMode = () => {
      const src = isSource();
      bUse.hidden = !src || !editor.use; bBlank.hidden = src; bAll.hidden = src; preview.hidden = src;
      note.textContent = src ? (sources.get(pick.value).note || "A whole tileset: Use in this map puts it in, and Publish takes it to the arena.") : STYLE_NOTE;
    };
    function setSources(list) {
      const was = pick.value;
      for (const g of [...pick.querySelectorAll("optgroup.src")]) g.remove();
      sources = new Map();
      const groups = new Map();
      for (const it of list || []) {
        if (!groups.has(it.group)) groups.set(it.group, h("optgroup", { label: it.group, className: "src" }));
        groups.get(it.group).append(h("option", { value: it.value, textContent: it.label }));
        sources.set(it.value, it);
      }
      pick.prepend(...groups.values());
      const own = (list || []).find((it) => it.own);
      if (touched && [...pick.options].some((o) => o.value === was)) pick.value = was;
      else pick.value = own ? own.value : og1.firstElementChild ? og1.firstElementChild.value : was;
      showMode(); showPreview().catch(() => {});
    }

    let before = null; // { prefix, tileset } to put back
    const showPreview = async () => {
      if (sources.has(pick.value)) return;
      await ready();
      const ctx = preview.getContext("2d");
      const st = stylesFor(pick.value, data);
      [[openMask("E"), 0], [openMask("EW"), 1], [openMask("SW"), 2], [0, 3]].forEach(([m, i]) => {
        const im = atlases.get(st[i % st.length]);
        ctx.drawImage(im, data.masks.indexOf(m) * TS, 0, TS, TS, i * TS, 0, TS, TS);
      });
    };
    const refresh = () => {
      const s = editor.get();
      const n = s.blank ? [...s.blank.keys()].filter(isWall).length : 0;
      bBlank.disabled = n === 0;
      bBlank.textContent = n ? `Paint ${n} blank slot${n === 1 ? "" : "s"}` : "Paint blank slots";
    };
    async function apply(kind) {
      try {
        await ready();
        const s = editor.get(), lay = await layout();
        const plan = kind === "blank" ? blankPlan(s.blank, s.grid, pick.value, data, lay) : restylePlan(s.grid, pick.value, data, lay);
        // Restyling keeps the old sheet only where the plan draws nothing: slots 162-190.
        const canvas = paint(s.tileset, plan, stylesFor(pick.value, data)[0]);
        if (!before) before = { prefix: s.prefix, tileset: s.tileset };
        editor.set(withTileset(s.prefix, rgbaOf(canvas)), canvas,
          `${kind === "blank" ? "Painted" : "Redrew"} ${plan.size} tile slots in ${pick.selectedOptions[0].textContent}. Publish to use it in game.`);
        bBack.hidden = false;
      } catch (err) { note.textContent = "Tile art failed: " + err.message; }
      refresh();
    }
    bBlank.addEventListener("click", () => apply("blank"));
    bAll.addEventListener("click", async () => {
      const text = "Redraw every wall slot this map uses in the new style? Decorations drawn in the old tileset (lettering, pictures) are replaced too. You can put the old tiles back.";
      if (await ask(text, { title: "Restyle all walls", ok: "Restyle" })) apply("all");
    });
    bUse.addEventListener("click", async () => {
      const s = editor.get(), prev = { prefix: s.prefix, tileset: s.tileset };
      bUse.disabled = true;
      try {
        if (await editor.use(pick.value, pick.selectedOptions[0].textContent)) { if (!before) before = prev; bBack.hidden = false; }
      } finally { bUse.disabled = false; }
      refresh();
    });
    bBack.addEventListener("click", () => {
      if (!before) return;
      editor.set(before.prefix, before.tileset, "Old tiles put back.");
      before = null; bBack.hidden = true; refresh();
    });
    pick.addEventListener("change", () => { touched = true; showMode(); showPreview().catch(() => {}); });
    showMode();
    showPreview().catch(() => {});
    refresh();
    return { refresh, setSources, forget: () => { before = null; bBack.hidden = true; refresh(); } };
  }

  window.TileArt = Object.assign(api, { data, ready, layout, paint, mount });
})();
